<?php
namespace App\Services;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\ValidationException;
use Carbon\CarbonImmutable;
final class PayrollAccess {
 public function __construct(public SchoolAccess $access){}
 public function fail(string $m):never{throw ValidationException::withMessages(['payroll'=>$m]);}
 public function can(Request $r,string $permission):bool{$key='payroll.permission.'.$permission;if(!$r->attributes->has($key))$r->attributes->set($key,$this->access->can($r,$permission));return $r->attributes->get($key);}
 public function finance(Request $r):bool{return $this->can($r,'payroll.manage')||$this->can($r,'payroll.approve')||$this->can($r,'payroll.view');}
 public function context(Request $r,?string $permission=null):array{if($permission)abort_unless($this->can($r,$permission),403);if($r->attributes->has('payroll.context'))return $r->attributes->get('payroll.context');abort_unless($this->finance($r)||$this->can($r,'staff.manage')||$this->can($r,'staff.attendance')||$this->can($r,'staff.leave_approve')||$this->can($r,'staff.self'),403);$m=$this->access->membership($r);$period=LicenseService::period($m->school_id);if($period)abort_unless(in_array('staff_payroll',json_decode($period->modules,true)??[],true),403,'Staff/payroll is not included in this school license.');$campuses=in_array('owner',$this->access->roles($m),true)?DB::table('campuses')->where('school_id',$m->school_id)->pluck('id')->all():array_map(fn($c)=>$c->id,$this->access->campuses($m));$context=[(int)$m->school_id,$m,array_map('intval',$campuses)];$r->attributes->set('payroll.context',$context);return $context;}
 // Take the shared money/workflow mutex before consistent reads establish their snapshot.
 public function lock(Request $r,?string $permission=null):int{$sid=(int)$this->access->membership($r)->school_id;DB::table('schools')->where('id',$sid)->lockForUpdate()->first();$this->context($r,$permission);return $sid;}
 public function campus(Request $r,int $id,bool $active=false):object{[$sid,,$campuses]=$this->context($r);abort_unless(in_array($id,$campuses,true),404);$c=DB::table('campuses')->where('school_id',$sid)->where('id',$id)->first()??abort(404);if($active&&$c->status!=='active')$this->fail('This campus is archived and cannot accept new payroll/attendance work.');return $c;}
 public function staff(Request $r,int $id,bool $self=false,bool $edit=false):object{[$sid,$m,$campuses]=$this->context($r);$p=DB::table('staff_profiles as p')->join('school_memberships as m','m.id','=','p.membership_id')->join('users as u','u.id','=','m.user_id')->where('p.school_id',$sid)->where('p.id',$id)->first(['p.*','u.name','u.email','m.status as membership_status'])??abort(404);if($self&&$p->membership_id===$m->id)return $p;$current=DB::table('staff_employments')->where('school_id',$sid)->where('staff_profile_id',$id)->where('starts_on','<=',$this->today())->where(fn($q)=>$q->whereNull('ends_on')->orWhere('ends_on','>=',$this->today()))->first();if($edit&&$current)abort_unless(in_array((int)$current->campus_id,$campuses,true),404);$job=DB::table('staff_employments')->where('school_id',$sid)->where('staff_profile_id',$id)->whereIn('campus_id',$campuses)->exists();$assigned=DB::table('membership_campuses')->where('school_id',$sid)->where('membership_id',$p->membership_id)->whereIn('campus_id',$campuses)->exists();abort_unless($job||$assigned,404);return $p;}
 public function month(string $month):array{$start=CarbonImmutable::createFromFormat('!Y-m',$month,'Asia/Karachi');return [$start->toDateString(),$start->endOfMonth()->toDateString(),$start->daysInMonth];}
 public function today():string{return now('Asia/Karachi')->toDateString();}
 public function money(int $n):string{return SchoolFees::money($n);}
 public function cents(mixed $v):int{if(!preg_match('/^\d{1,8}(?:\.\d{1,2})?$/D',(string)$v))$this->fail('Use non-negative PKR amounts with up to two decimals (maximum 99999999.99).');return SchoolFees::cents((string)$v);}
 public function ratio(int $amount,int $days,int $denominator):int{return intdiv($amount*$days+intdiv($denominator,2),$denominator);}
 public function bank(Request $r,?int $bank,int $campus,string $method):void{[$sid,,$campuses]=$this->context($r);if($method==='cash'){if($bank)$this->fail('Cash transactions must not select a bank account.');return;}if(!$bank)$this->fail('Select the receiving/paying bank account.');$b=DB::table('bank_accounts')->where('school_id',$sid)->where('id',$bank)->first()??abort(404);if($b->campus_id!==null&&($b->campus_id!==$campus||!in_array((int)$b->campus_id,$campuses,true)))$this->fail('Choose an account for this campus or a school-wide bank account.');}
 public function item(Request $r,int $id,bool $self=false):array{[$sid,$m]=$this->context($r);$item=DB::table('payroll_items')->where('school_id',$sid)->where('id',$id)->first()??abort(404);$run=DB::table('payroll_runs')->where('school_id',$sid)->where('id',$item->payroll_run_id)->first()??abort(404);$p=DB::table('staff_profiles')->where('school_id',$sid)->where('id',$item->staff_profile_id)->first()??abort(404);if(!($self&&$this->can($r,'staff.self')&&$p->membership_id===$m->id)){abort_unless($this->finance($r),403);$this->campus($r,$run->campus_id);}return [$item,$run,$p];}
}
